      title: 'Refund, Replacement & Cancellation Policy',
      lastUpdated: 'Last updated: August 4, 2026',
      intro: 'Flowers are seasonal and perishable. This policy explains issue reporting, order cancellation, and refund handling across all delivery zones. If something isn\'t right, please tell us quickly and we will review the case as soon as possible.',
      timeLimitTitle: '1) Time limit to report an issue',
      timeLimitText:
        'To be eligible for a replacement or refund, you must contact us within 2 hours of delivery. You can reach us on LINE or WhatsApp, or — when available — through the temporary chat on your order tracking page. That order-page chat stays open for the same 2-hour window after delivery, then its message history is permanently deleted.',
      eligibleTitle: '2) Eligible for replacement or refund',
      eligibleIntro: 'You may be eligible if the bouquet arrives:',
      eligibleList1: 'Damaged (e.g., crushed, broken stems, severe packaging damage affecting the bouquet)',
      eligibleList2: 'Wilted / not in deliverable condition on arrival',
      eligibleList3: 'Significantly different from the confirmed order (style/value)',
      eligibleOutro: 'If confirmed, we may offer:',
      eligibleOption1: 'Replacement bouquet (same value), or',
      eligibleOption2: 'Refund (full or partial, depending on the case)',
      keepBouquetNote: 'Please keep the bouquet until we confirm the outcome. If it is discarded before review, we may not be able to approve a replacement/refund.',
      whatToSendTitle: '3) What to send us (required)',
      whatToSendIntro: 'Please contact us via',
      whatToSendIntroSuffix:
        ', or use the temporary chat on your order page when it is available, and send:',
      contactOnLine: 'Contact on LINE',
      contactOnWhatsApp: 'Contact on WhatsApp',
      contactOnOrderChat: 'temporary order-page chat',
      whatToSendList1: 'Order number or order link',
      whatToSendList2: 'Delivery date/time',
      whatToSendList3: 'Clear photos of the bouquet (and packaging if relevant)',
      whatToSendList4: 'A short note describing the issue',
      orderChatNote:
        'Note: the temporary order-page chat does not support photo attachments. If you need to send photos, please use LINE or WhatsApp and include your order number or order link.',
      notEligibleTitle: '4) Not eligible (important)',
      notEligibleIntro: 'Refunds/replacements may not apply if:',
      notEligible1: 'You contact us after 2 hours from delivery',
      notEligible2: 'Damage happens after delivery due to heat, lack of water, handling, or leaving the bouquet outdoors',
      notEligible3: 'The bouquet differs only by minor natural variations (size, bloom stage, shade differences)',
      notEligible4: 'The issue is caused by incorrect/incomplete delivery details (wrong address/phone, missing room number, access instructions)',
      notEligible5: 'The recipient is unavailable and delivery cannot be completed after reasonable contact attempts',
      notEligible6: 'The request is a change of mind after confirmation, after preparation has started, or after dispatch',
      aiImagesTitle: '5) Product images, AI visuals, and natural variation',
      aiImagesIntro: 'Some images on our website are AI-generated or styled as visual references. They show the overall mood, color palette, and bouquet style, not an exact one-to-one copy.',
      aiImagesBody: 'Because flowers are seasonal and natural, the final bouquet may differ in:',
      aiImagesList1: 'exact flower varieties/greenery used',
      aiImagesList2: 'placement and shape of stems',
      aiImagesList3: 'wrapping details',
      aiImagesList4: 'small color shade differences',
      aiImagesOutro: 'As long as the delivered bouquet matches the intended style and overall value, these differences are not eligible for a refund or replacement. (This does not affect cases where the bouquet arrives damaged or wilted.)',
      substitutionsTitle: '6) Substitutions (seasonal availability)',
      substitutionsIntro: 'If substitutions are needed due to availability, we aim to keep:',
      substitutions1: 'the same overall style',
      substitutions2: 'similar colors (when possible)',
      substitutions3: 'the same or higher value',
      deliveryIssuesTitle: '7) Delivery issues and re-delivery',
      deliveryIssues: 'If delivery cannot be completed because the recipient is unavailable, access is restricted, or details are incorrect/incomplete, we may return the bouquet or arrange re-delivery when possible. If the location or zone you provided was wrong and extra delivery cost applies, we will contact you to approve any additional fee before we reroute or try again. At arrival, we target handover within 15 minutes and do not keep the driver waiting on site longer than 30 minutes in total; if extra waiting is caused by the customer or recipient, we may charge an additional driver waiting fee. Additional delivery fees may apply for re-delivery or rerouting caused by these situations, and cancellations requested at this stage may not be fully refundable.',
      refundMethodTitle: '8) Refund method, timing, and Stripe fees',
      refundMethod1: 'Refunds are issued to the original payment method where possible.',
      refundMethod2: 'Card refunds can take time to appear, depending on your bank/card issuer (often 5–14 business days, sometimes longer).',
      refundMethod3: 'Stripe\'s processing fees from the original transaction aren\'t returned to us when a card payment is refunded.',
